const items = $input.all();
const webhookData = $('Webhook Trigger').first().json.body;

// === UMBRALES POR PRODUCTO (sistema conservador) ===
const PRODUCTOS = {
  'glifosato': { viento_max: 16, temp_min: 10, temp_max: 30, humedad_min: 55, rainfast: 2, riesgo_deriva: 'medio' },
  '2,4-d': { viento_max: 15, temp_min: 10, temp_max: 25, humedad_min: 55, rainfast: 1, riesgo_deriva: 'alto' },
  'dicamba': { viento_max: 12, temp_min: 10, temp_max: 29, humedad_min: 55, rainfast: 3, riesgo_deriva: 'muy_alto' },
  'fomesafen': { viento_max: 16, temp_min: 15, temp_max: 30, humedad_min: 60, rainfast: 2, riesgo_deriva: 'medio' },
  'elatus': { viento_max: 15, temp_min: 15, temp_max: 30, humedad_min: 60, rainfast: 2, riesgo_deriva: 'bajo' },
  'fox_xpro': { viento_max: 15, temp_min: 10, temp_max: 30, humedad_min: 55, rainfast: 2, riesgo_deriva: 'bajo' },
  'bumper': { viento_max: 15, temp_min: 10, temp_max: 30, humedad_min: 55, rainfast: 2, riesgo_deriva: 'bajo' },
  'lambda_cialotrina': { viento_max: 24, temp_min: 10, temp_max: 32, humedad_min: 50, rainfast: 2, riesgo_deriva: 'medio', restriccion_inversion: true },
  'metomil': { viento_max: 16, temp_min: 15, temp_max: 32, humedad_min: 50, rainfast: 4, riesgo_deriva: 'medio', restringido: true },
  'bt': { viento_max: 15, temp_min: 15, temp_max: 30, humedad_min: 60, rainfast: 4, riesgo_deriva: 'bajo' },
};

// === CONDICIONES SIEMBRA ===
const CONDICIONES_SIEMBRA = {
  'soya': { temp_suelo_min: 10, humedad_suelo_min: 50, lluvia_min_7d: 10 },
  'maiz': { temp_suelo_min: 10, humedad_suelo_min: 50, lluvia_min_7d: 15 },
};

// === EXTRAER DATOS DE OPEN-METEO ===
let openMeteo = null;
for (const item of items) {
  const d = item.json;
  if (d.current && d.current.temperature_2m !== undefined) {
    openMeteo = {
      temperatura: d.current.temperature_2m,
      humedad: d.current.relative_humidity_2m,
      viento: d.current.wind_speed_10m,
      viento_dir: d.current.wind_direction_10m,
      precipitacion: d.current.precipitation || 0,
      nubosidad: d.current.cloud_cover,
      uv: d.current.uv_index,
      temp_suelo: d.hourly?.soil_temperature_0cm?.[0] || null,
      humedad_suelo: d.hourly?.soil_moisture_0_to_1cm?.[0] || null,
      pronostico_horas: []
    };
    for (let i = 0; i < Math.min(6, d.hourly?.time?.length || 0); i++) {
      openMeteo.pronostico_horas.push({
        hora: d.hourly.time[i],
        viento: d.hourly.wind_speed_10m?.[i],
        prob_lluvia: d.hourly.precipitation_probability?.[i] || 0,
        temp: d.hourly.temperature_2m?.[i]
      });
    }
    break;
  }
}

// === EXTRAER DATOS DE WTTR ===
let wttr = null;
for (const item of items) {
  const d = item.json;
  if (d.current_condition && d.current_condition[0]) {
    const c = d.current_condition[0];
    wttr = {
      temperatura: parseFloat(c.temp_C),
      humedad: parseFloat(c.humidity),
      viento: parseFloat(c.windspeedKmph),
      uv: parseFloat(c.uvIndex),
      precipitacion: parseFloat(c.precipMM),
      nubosidad: parseFloat(c.cloudcover)
    };
    break;
  }
}

// === PROMEDIAR FUENTES ===
const promedio = (campo) => {
  const vals = [];
  if (openMeteo && openMeteo[campo] !== null && openMeteo[campo] !== undefined) vals.push(openMeteo[campo]);
  if (wttr && wttr[campo] !== null && wttr[campo] !== undefined) vals.push(wttr[campo]);
  if (vals.length === 0) return null;
  return Math.round(vals.reduce((a, b) => a + b, 0) / vals.length * 10) / 10;
};

const condiciones = {
  temperatura_c: promedio('temperatura'),
  humedad_pct: promedio('humedad'),
  viento_kmh: promedio('viento'),
  uv_index: promedio('uv'),
  precipitacion_mm: promedio('precipitacion'),
  nubosidad_pct: promedio('nubosidad'),
  temp_suelo_c: openMeteo?.temp_suelo || null,
  humedad_suelo_pct: openMeteo?.humedad_suelo || null,
};

// Prob lluvia 6h del pronóstico
let prob_lluvia_6h = 0;
if (openMeteo?.pronostico_horas) {
  const probs = openMeteo.pronostico_horas.map(h => h.prob_lluvia || 0);
  prob_lluvia_6h = Math.max(...probs);
}

// === DETECCIÓN INVERSIÓN TÉRMICA (heurística) ===
const ahora = new Date();
const horaLocal = ahora.getHours();
const esHorarioPeligroso = horaLocal >= 17 || horaLocal <= 7;
const vientoCalmo = condiciones.viento_kmh < 3;
const cieloDespejado = (condiciones.nubosidad_pct || 100) < 30;
const inversionTermica = esHorarioPeligroso && vientoCalmo && cieloDespejado;

// === EVALUAR FUMIGACIÓN ===
const accion = webhookData.accion || 'fumigar';
const producto = webhookData.producto || '';
const cultivo = webhookData.cultivo || '';

let veredicto = '';
let semaforo = '';
let advertencias = [];
let umbrales_aplicados = {};

if (accion === 'fumigar' && producto) {
  const prod = PRODUCTOS[producto.toLowerCase().replace(/ /g, '_')];
  if (prod) {
    umbrales_aplicados = {
      producto: producto,
      viento_max_kmh: prod.viento_max,
      temp_min_c: prod.temp_min,
      temp_max_c: prod.temp_max,
      humedad_min_pct: prod.humedad_min,
      rainfast_horas: prod.rainfast
    };

    if (condiciones.viento_kmh > prod.viento_max)
      advertencias.push({ tipo: 'viento', severidad: 'alta', mensaje: `Viento ${condiciones.viento_kmh} km/h excede máximo ${prod.viento_max} km/h para ${producto}` });
    if (condiciones.temperatura_c < prod.temp_min)
      advertencias.push({ tipo: 'temp_baja', severidad: 'alta', mensaje: `Temperatura ${condiciones.temperatura_c}°C por debajo del mínimo ${prod.temp_min}°C` });
    if (condiciones.temperatura_c > prod.temp_max)
      advertencias.push({ tipo: 'temp_alta', severidad: 'alta', mensaje: `Temperatura ${condiciones.temperatura_c}°C excede máximo ${prod.temp_max}°C` });
    if (condiciones.humedad_pct < prod.humedad_min)
      advertencias.push({ tipo: 'humedad_baja', severidad: 'media', mensaje: `Humedad ${condiciones.humedad_pct}% por debajo del mínimo ${prod.humedad_min}%` });
    if (prob_lluvia_6h > 30)
      advertencias.push({ tipo: 'lluvia', severidad: 'alta', mensaje: `Probabilidad de lluvia ${prob_lluvia_6h}% - riesgo de lavado del producto` });
    if (inversionTermica)
      advertencias.push({ tipo: 'inversion_termica', severidad: 'alta', mensaje: 'Riesgo de inversión térmica detectado (viento calmo + horario peligroso + cielo despejado)' });
    if (prod.restriccion_inversion)
      advertencias.push({ tipo: 'restriccion', severidad: 'critica', mensaje: `${producto} tiene restricción explícita: NO aplicar durante inversiones térmicas` });
    if (prod.restringido)
      advertencias.push({ tipo: 'legal', severidad: 'critica', mensaje: `${producto} es de uso RESTRINGIDO en Bolivia. Requiere receta SENASAG.` });
  } else {
    advertencias.push({ tipo: 'producto_no_encontrado', severidad: 'alta', mensaje: `Producto '${producto}' no encontrado en la base de datos` });
  }
} else if (accion === 'sembrar' && cultivo) {
  const cond = CONDICIONES_SIEMBRA[cultivo.toLowerCase()];
  if (cond) {
    umbrales_aplicados = {
      cultivo: cultivo,
      temp_suelo_min: cond.temp_suelo_min,
      humedad_suelo_min: cond.humedad_suelo_min,
      lluvia_min_7dias: cond.lluvia_min_7d
    };
    if (condiciones.temp_suelo_c !== null && condiciones.temp_suelo_c < cond.temp_suelo_min)
      advertencias.push({ tipo: 'temp_suelo_baja', severidad: 'alta', mensaje: `Temperatura suelo ${condiciones.temp_suelo_c}°C por debajo del mínimo ${cond.temp_suelo_min}°C` });
    if (condiciones.humedad_suelo_pct !== null && condiciones.humedad_suelo_pct < cond.humedad_suelo_min)
      advertencias.push({ tipo: 'humedad_suelo_baja', severidad: 'alta', mensaje: `Humedad suelo ${condiciones.humedad_suelo_pct}% por debajo del mínimo ${cond.humedad_suelo_min}%` });
  }
}

// === SEMÁFORO ===
const criticas = advertencias.filter(a => a.severidad === 'alta' || a.severidad === 'critica');
const medias = advertencias.filter(a => a.severidad === 'media');

if (criticas.length > 0) {
  veredicto = accion === 'fumigar' ? 'NO_SEGURO' : 'DESFAVORABLE';
  semaforo = 'rojo';
} else if (medias.length > 0) {
  veredicto = accion === 'fumigar' ? 'PRECAUCION' : 'MARGINAL';
  semaforo = 'amarillo';
} else {
  veredicto = accion === 'fumigar' ? 'SEGURO' : 'FAVORABLE';
  semaforo = 'verde';
}

// === RECOMENDACIÓN ===
let recomendacion = '';
if (semaforo === 'rojo') {
  const principal = advertencias[0];
  recomendacion = `No ${accion === 'fumigar' ? 'fumbiques' : 'siembres'} hoy. ${principal?.mensaje || ''}. `;
  if (openMeteo?.pronostico_horas?.length > 0) {
    const mejorHora = openMeteo.pronostico_horas.find(h => h.viento < 10 && h.prob_lluvia < 20);
    if (mejorHora) recomendacion += `Mejor ventana: ${mejorHora.hora}.`;
  }
} else if (semaforo === 'amarillo') {
  recomendacion = `Precaución: ${advertencias.map(a => a.mensaje).join('. ')}. Considere esperar.`;
} else {
  recomendacion = accion === 'fumigar'
    ? `Condiciones favorables para fumigar. Viento ${condiciones.viento_kmh} km/h, temperatura ${condiciones.temperatura_c}°C, humedad ${condiciones.humedad_pct}%.`
    : `Condiciones favorables para sembrar ${cultivo}. Temperatura suelo ${condiciones.temp_suelo_c || 'N/A'}°C.`;
}

return [{
  json: {
    success: true,
    timestamp: new Date().toISOString(),
    ubicacion: {
      lat: webhookData.latitude,
      lon: webhookData.longitude
    },
    accion_evaluada: accion,
    producto_evaluado: producto || null,
    cultivo_evaluado: cultivo || null,
    veredicto: veredicto,
    semaforo: semaforo,
    condiciones_actuales: condiciones,
    pronostico_6h: {
      prob_lluvia_max_pct: prob_lluvia_6h,
      horas: openMeteo?.pronostico_horas || []
    },
    umbrales_aplicados: umbrales_aplicados,
    advertencias: advertencias,
    inversion_termica_detectada: inversionTermica,
    recomendacion: recomendacion,
    fuentes_usadas: [openMeteo ? 'openmeteo' : null, wttr ? 'wttr' : null].filter(Boolean)
  }
}];
